#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""W009 Q6600 kit driver: build FCMP++ txs with exactly n inputs on a wallet-rpc, NEVER relayed.

Freezes every output of the opened wallet, then for each run thaws n outputs (oldest first, by global index) and calls
sweep_all(do_not_relay=True, subaddr_indices_all=True) to the wallet's own address, so the thawed outputs are swept from
every subaddress of account 0 (without it, wallet2 sweeps one random non-empty subaddress only). Each result is checked:
the tx's spent key images must be exactly the n thawed ones, or the run stops with an error. The built tx is discarded: do_not_relay is hard-wired below,
and this script calls no relay method. Records RPC wall time and the wallet-rpc process's CPU time over the call.

RUN ONLY ON A COPY OF A WALLET: it freezes outputs (stored in the wallet file). It refuses to run unless the
environment variable I_AM_A_COPY=yes is set.

usage: q6600_drive.py <wallet-rpc port> <wallet-rpc pid> <wallet file name> <arm label> <out csv> <n,n,...> [prep]
"""
import json, os, sys, time, urllib.request, hashlib
if os.environ.get("I_AM_A_COPY") != "yes":
    sys.exit("refusing: set I_AM_A_COPY=yes, and run this only on a copy of a wallet")
port, pid, wname, arm, out, ns = int(sys.argv[1]), int(sys.argv[2]), sys.argv[3], sys.argv[4], sys.argv[5], [int(x) for x in sys.argv[6].split(",")]
prep = len(sys.argv) > 7 and sys.argv[7] == "prep"
URL = f"http://127.0.0.1:{port}/json_rpc"
def rpc(method, params=None, timeout=7200):
    assert method not in ("relay_tx", "submit_transfer", "send_raw_transaction"), "this kit never relays"
    req = urllib.request.Request(URL, data=json.dumps({"jsonrpc": "2.0", "id": 0, "method": method, "params": params or {}}).encode(),
                                 headers={"Content-Type": "application/json"})
    r = json.loads(urllib.request.urlopen(req, timeout=timeout).read())
    if "error" in r: raise RuntimeError(f"{method}: {r['error']}")
    return r["result"]
def cpu_s(p):
    f = open(f"/proc/{p}/stat").read().rsplit(")", 1)[1].split()
    return (int(f[11]) + int(f[12])) / os.sysconf("SC_CLK_TCK")
exe = os.readlink(f"/proc/{pid}/exe"); exe_sha = hashlib.sha256(open(exe, "rb").read()).hexdigest()[:16]
rpc("open_wallet", {"filename": wname, "password": os.environ.get("WALLET_PASSWORD", "")}, timeout=600)
rpc("refresh", {}, timeout=3600)
tr = rpc("incoming_transfers", {"transfer_type": "available", "account_index": 0}).get("transfers", [])
if prep:
    for t in tr:
        if not t.get("frozen"): rpc("freeze", {"key_image": t["key_image"]})
    rpc("store", {}); print(f"{arm}: froze {len(tr)} outputs", flush=True)
pool = sorted([t for t in tr if t.get("unlocked", True)], key=lambda t: t["global_index"])
need = max(ns)
if len(pool) < need: sys.exit(f"{arm}: only {len(pool)} unlocked outputs, need {need}")
print(f"{arm}: {len(tr)} available outputs, {len(pool)} unlocked; using the {need} oldest; "
      f"subaddresses among them: {len({(t['subaddr_index']['major'], t['subaddr_index']['minor']) for t in pool[:need]})}", flush=True)
pool = pool[:need]
addr = rpc("get_address", {"account_index": 0})["address"]
new = not os.path.exists(out)
with open(out, "a") as f:
    if new: f.write("utc,arm,exe_sha,n_inputs,wall_s,cpu_s,cpu_per_wall,n_txs,fee,weight\n")
    for n in ns:
        for t in pool[:n]: rpc("thaw", {"key_image": t["key_image"]})
        c0, t0 = cpu_s(pid), time.time()
        res = rpc("sweep_all", {"address": addr, "account_index": 0, "subaddr_indices_all": True, "do_not_relay": True, "priority": 0})
        t1, c1 = time.time(), cpu_s(pid)
        for t in pool[:n]: rpc("freeze", {"key_image": t["key_image"]})
        spent = [k for x in res.get("spent_key_images_list", []) for k in x.get("key_images", [])]
        want = {t["key_image"] for t in pool[:n]}
        if len(res.get("tx_hash_list", [])) != 1 or len(spent) != n or set(spent) != want:
            sys.exit(f"{arm}: n={n}: the tx does not spend exactly the {n} thawed outputs "
                     f"(txs {len(res.get('tx_hash_list', []))}, key images {len(spent)}, match {set(spent) == want}); stopping")
        line = (f"{time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime(t0))},{arm},{exe_sha},{n},{t1 - t0:.2f},{c1 - c0:.2f},"
                f"{(c1 - c0) / (t1 - t0):.2f},{len(res.get('tx_hash_list', []))},{sum(res.get('fee_list', [0]))},{sum(res.get('weight_list', [0]))}")
        f.write(line + "\n"); f.flush(); print(line, flush=True)
rpc("store", {}); rpc("close_wallet", {})
